                                  'tblmmvno', 'tblstaffuser','tblroles', 'tblstaffrolerel', 'tbltstaffbusinessunitrel',
                                  'tblmstaffledgerdetails', 'tbltstaffservicearearel','tbltstaffuserreceiptmapping',
                                  'tblmclientservice','tblteams'
             );
         DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
	SET FOREIGN_KEY_CHECKS = 0;
         OPEN cur;
         read_loop: LOOP
     FETCH cur INTO tableName;
     IF done THEN
         LEAVE read_loop;
         END IF;
     SET @sql = CONCAT('UPDATE ', tableName, ' SET mvnoId =',new_mvnoid,' WHERE mvnoId = ', old_mvnoid ,';');
         select @sql;
         PREPARE stmt FROM @sql;
         EXECUTE stmt;
         DEALLOCATE PREPARE stmt;
         END LOOP;
         CLOSE cur;
         SET FOREIGN_KEY_CHECKS = 1;
         END//
